import argparse
from util import normalize

def main():
    p = argparse.ArgumentParser(prog="tagger", description="normalize product tags")
    p.add_argument("--tag", help="normalize a single tag and print it")
    args = p.parse_args()
    if args.tag:
        print(normalize(args.tag))

if __name__ == "__main__":
    main()
